import math
def act(x) :
    return math.tanh(x)

def policy_forward(obs):
    x=list(obs)

    # Layer 0 : (4 -> 64)
    next=[0.0]*64
    for o in range(64):
        s=policy_b0[o]
        for j in range(4):
            s += policy_w0[o][j] * x[j]
        next[o] = act(s)
    x=next

    # Layer 1 : (64 -> 64)
    next=[0.0]*64
    for o in range(64):
        s=policy_b1[o]
        for j in range(64):
            s += policy_w1[o][j] * x[j]
        next[o] = act(s)
    x=next

    # Layer 2 : (64 -> 2)
    next=[0.0]*2
    for o in range(2):
        s=policy_b2[o]
        for j in range(64):
            s += policy_w2[o][j] * x[j]
        next[o] = s  # linear output
    x=next

    return x
